import 'package:flutter/material.dart';
void main()=>runApp(MaterialApp(debugShowCheckedModeBanner:false,theme:ThemeData.dark().copyWith(scaffoldBackgroundColor:Color(0xFF121212)),home:MainPage()));
class MainPage extends StatefulWidget{@override State<MainPage> createState()=>_MainPageState();}
class _MainPageState extends State<MainPage>{int idx=0;@override Widget build(BuildContext context){return Scaffold(body:[MatchsPage(),FavPage(),ExpPage(),TransPage(),InfosPage()][idx],bottomNavigationBar:BottomNavigationBar(currentIndex:idx,onTap:(x)=>setState(()=>idx=x),type:BottomNavigationBarType.fixed,backgroundColor:Color(0xFF1E1E1E),selectedItemColor:Color(0xFF1DBE60),unselectedItemColor:Colors.grey,items:[BottomNavigationBarItem(icon:Icon(Icons.sports_soccer),label:"Matchs"),BottomNavigationBarItem(icon:Icon(Icons.star),label:"Favoris"),BottomNavigationBarItem(icon:Icon(Icons.explore),label:"Explorer"),BottomNavigationBarItem(icon:Icon(Icons.swap_horiz),label:"Transferts"),BottomNavigationBarItem(icon:Icon(Icons.article),label:"Infos")]));}}
Widget realLogo(String team){String f=team.substring(0,2).toUpperCase();Color bg=Colors.white;Color txt=Colors.black;double s=20;if(team.contains("Somalie")){f="🇸🇴";bg=Color(0xFF418FDE);}else if(team.contains("Côte")){f="🇨🇮";}else if(team.contains("Barcelona")){f="🔵🔴";bg=Color(0xFFA50044);txt=Colors.white;s=14;}else if(team.contains("ASEC")){f="💛";bg=Color(0xFFFFD700);}else if(team.contains("Africa")){f="💚";bg=Color(0xFF008000);txt=Colors.white;}else if(team.contains("Stella")){f="❤️";bg=Color(0xFFD00000);txt=Colors.white;}else if(team.contains("City")){f="💙";bg=Color(0xFF6CABDD);}else if(team.contains("Arsenal")){f="🔴";bg=Color(0xFFEF0107);txt=Colors.white;}return Container(width:44,height:44,decoration:BoxDecoration(color:bg,shape:BoxShape.circle,border:Border.all(color:Colors.white24)),child:Center(child:Text(f,style:TextStyle(fontSize:s,fontWeight:FontWeight.bold,color:txt))));}
class MatchsPage extends StatelessWidget{@override Widget build(BuildContext context){return Column(children:[Container(color:Color(0xFF1E1E1E),padding:EdgeInsets.only(top:36,left:12,right:12,bottom:8),child:Row(children:[Text("BESOCCER",style:TextStyle(fontWeight:FontWeight.bold)),Spacer(),Icon(Icons.calendar_today,size:18)])),Expanded(child:ListView(padding:EdgeInsets.all(8),children:[Container(padding:EdgeInsets.all(14),decoration:BoxDecoration(color:Color(0xFF1DBE60),borderRadius:BorderRadius.circular(10)),child:Text("V22 - VRAIS DRAPEAUX 🇨🇮🇸🇴 OFFLINE",style:TextStyle(fontWeight:FontWeight.bold,color:Colors.white))),SizedBox(height:8),sec("FAVORIS - COTE D'IVOIRE 🇨🇮",[mRow(context,"Somalie","0 - 2\nTF","Côte d'Ivoire")]),sec("LONACI LIGUE 1 🇨🇮",[mRow(context,"ASEC Mimosas","15:30","Africa Sport"),mRow(context,"Stella Club","15:30","FC San Pedro")]),sec("PREMIER LEAGUE",[mRow(context,"Man City","18:30","Arsenal")])]))]);}}
Widget sec(String t,List<Widget> r)=>Container(margin:EdgeInsets.only(bottom:8),decoration:BoxDecoration(color:Color(0xFF2A2A2A),borderRadius:BorderRadius.circular(10)),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Padding(padding:EdgeInsets.all(10),child:Text(t,style:TextStyle(fontSize:11,fontWeight:FontWeight.bold))),...r]));
Widget mRow(BuildContext c,String t1,String sc,String t2)=>Container(padding:EdgeInsets.symmetric(horizontal:10,vertical:12),decoration:BoxDecoration(border:Border(top:BorderSide(color:Colors.white10))),child:Row(children:[Expanded(child:Text(t1,textAlign:TextAlign.right,style:TextStyle(fontSize:13))),SizedBox(width:8),realLogo(t1),SizedBox(width:10),Container(width:55,child:Text(sc,textAlign:TextAlign.center,style:TextStyle(fontWeight:FontWeight.bold,fontSize:12))),SizedBox(width:10),realLogo(t2),SizedBox(width:8),Expanded(child:Text(t2,style:TextStyle(fontSize:13)))]));
class FavPage extends StatelessWidget{@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text("Favoris")),body:GridView.count(crossAxisCount:3,padding:EdgeInsets.all(16),children:[for(var n in ["FC Barcelona","Côte d'Ivoire","Somalie","ASEC Mimosas"]) Column(children:[realLogo(n),Text(n)])]));}}
class ExpPage extends StatelessWidget{@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text("Explorer")),body:Center(child:Text("211 pays")));}}
class TransPage extends StatelessWidget{@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text("Transferts")),body:Center(child:Text("LONACI")));}}
class InfosPage extends StatelessWidget{@override Widget build(BuildContext c){return Scaffold(appBar:AppBar(title:Text("Infos")),body:Center(child:Text("V22 OFFLINE 🇨🇮🇸🇴")));}}
